import * as React from "react";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";

type ReferenceColumn = {
  header: string;
  /** A literal width class: Tailwind only emits utilities it sees spelled out. Omit on the column that takes the remaining width. */
  width?: string;
};

export type ReferenceRow = {
  key: string;
  cells: React.ReactNode[];
};

export function ReferenceTable({
  columns,
  rows,
}: {
  columns: ReferenceColumn[];
  rows: ReferenceRow[];
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      {/* table-fixed so a long cell cannot widen its column past the declared width. */}
      <Table className="table-fixed">
        <TableHeader>
          <TableRow className="bg-muted/40 hover:bg-muted/40">
            {columns.map((column) => (
              <TableHead
                className={cn(
                  "h-11 px-4 text-xs font-medium text-muted-foreground",
                  column.width,
                )}
                key={column.header}
              >
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.key}>
              {row.cells.map((cell, index) => (
                <TableCell
                  /* `whitespace-normal` undoes the primitive's nowrap so prose stays inside the declared width. */
                  className="px-4 py-3.5 align-top whitespace-normal"
                  key={columns[index]?.header ?? index}
                >
                  {cell}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

export function ReferenceName({ children }: { children: React.ReactNode }) {
  return <span className="font-mono text-sm">{children}</span>;
}

export function ReferenceLabel({ children }: { children: React.ReactNode }) {
  return <span className="text-sm font-medium">{children}</span>;
}

export function ReferenceNote({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-sm leading-relaxed text-muted-foreground">
      {children}
    </span>
  );
}

"use client";

import * as React from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Input } from "@/components/ui/input";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemTitle,
} from "@/components/ui/item";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { TabsContent } from "@/components/ui/tabs";
import { PageHeader } from "@/components/shared/page-header";
import {
  CreateInListIcon,
  RowMenuIcon,
  SectionToggleIcon,
} from "@/components/design-system/icons";
import { SecondaryTabs } from "@/components/design-system/tabs-preview";
import { cn } from "@/lib/utils";

type SectionId = "first-message" | "variables" | "analytics" | "tools" | "kb";

type Section = {
  id: SectionId;
  title: string;
  description: string;
  count?: number;
  toggle?: string;
  add?: string;
};

const SECTIONS: Section[] = [
  {
    id: "first-message",
    title: "First message",
    description:
      "What the agent says when the call connects. {{name}} is filled in per call.",
    toggle: "Open with this message",
  },
  {
    id: "variables",
    title: "Template variables",
    description: "Found in the prompt and the first message.",
    count: 4,
  },
  {
    id: "analytics",
    title: "Call analytics and data collection",
    description:
      "What the agent gathers from each conversation, for reports and your CRM.",
    count: 3,
    toggle: "Collect data",
  },
  {
    id: "tools",
    title: "Agent tools",
    description: "What the agent can do during a call besides talk.",
    count: 3,
    add: "Add tool",
  },
  {
    id: "kb",
    title: "Knowledge bases",
    description:
      "Searched when a question needs them. Say when each one applies.",
    count: 2,
    add: "Attach",
  },
];

const VARIABLES = [
  { name: "name", type: "Text", required: true },
  { name: "account_number", type: "Text", required: true },
  { name: "due_date", type: "Date", required: false },
  { name: "amount_due", type: "Number", required: false },
];

const FIELDS = [
  { name: "Payment promised", type: "Yes or no" },
  { name: "Promise date", type: "Date" },
  { name: "Reason for delay", type: "Text" },
];

const TOOLS = [
  { name: "End call", detail: "Hangs up with a polite goodbye" },
  { name: "Schedule callback", detail: "Books a time to call back" },
  { name: "Collect digits", detail: "Reads a number typed on the keypad" },
];

const KNOWLEDGE = [
  { name: "Payment FAQ", detail: "When the customer asks how to pay" },
  { name: "Late fees 2026", detail: "When the customer disputes a fee" },
];

const FIRST_MESSAGE =
  "Hi {{name}}, this is Sara from Sarj. Is now a good time to talk?";

type Toggles = Record<SectionId, boolean>;

function useToggles() {
  const [on, setOn] = React.useState<Toggles>({
    "first-message": true,
    variables: true,
    analytics: true,
    tools: true,
    kb: true,
  });
  const set = (id: SectionId, value: boolean) =>
    setOn((current) => ({ ...current, [id]: value }));
  return { on, set };
}

function summary(id: SectionId, on: boolean) {
  if (!on) return "Off";
  switch (id) {
    case "first-message":
      return FIRST_MESSAGE;
    case "variables":
      return `${VARIABLES.filter((v) => v.required).length} required`;
    case "analytics":
      return FIELDS.map((field) => field.name).join(", ");
    case "tools":
      return TOOLS.map((tool) => tool.name).join(", ");
    case "kb":
      return KNOWLEDGE.map((kb) => kb.name).join(", ");
  }
}

function Body({ id }: { id: SectionId }) {
  switch (id) {
    case "first-message":
      return <Input aria-label="First message" defaultValue={FIRST_MESSAGE} />;
    case "variables":
      return (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Variable</TableHead>
              <TableHead>Type</TableHead>
              <TableHead className="text-end">Required</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {VARIABLES.map((variable) => (
              <TableRow key={variable.name}>
                <TableCell className="font-mono text-xs">
                  {variable.name}
                </TableCell>
                <TableCell className="text-muted-foreground">
                  {variable.type}
                </TableCell>
                <TableCell className="text-end">
                  <Switch
                    aria-label={`${variable.name} required`}
                    defaultChecked={variable.required}
                    size="sm"
                  />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      );
    case "analytics":
      return (
        <Rows rows={FIELDS.map((f) => ({ name: f.name, detail: f.type }))} />
      );
    case "tools":
      return <Rows rows={TOOLS} />;
    case "kb":
      return <Rows rows={KNOWLEDGE} />;
  }
}

function Rows({ rows }: { rows: { name: string; detail: string }[] }) {
  return (
    <ItemGroup className="gap-2">
      {rows.map((row) => (
        <Item key={row.name} size="sm" variant="outline">
          <ItemContent>
            <ItemTitle>{row.name}</ItemTitle>
            <ItemDescription>{row.detail}</ItemDescription>
          </ItemContent>
          <ItemActions>
            <Button
              aria-label={`${row.name} options`}
              size="icon-sm"
              variant="ghost"
            >
              <RowMenuIcon />
            </Button>
          </ItemActions>
        </Item>
      ))}
    </ItemGroup>
  );
}

function Control({
  section,
  on,
  onToggle,
}: {
  section: Section;
  on: boolean;
  onToggle: (value: boolean) => void;
}) {
  if (section.toggle)
    return (
      <Switch
        aria-label={section.toggle}
        checked={on}
        onCheckedChange={onToggle}
      />
    );
  if (section.add)
    return (
      <Button size="sm" variant="outline">
        <CreateInListIcon />
        {section.add}
      </Button>
    );
  return null;
}

function Title({
  section,
  onBand = false,
}: {
  section: Section;
  onBand?: boolean;
}) {
  return (
    <div className="flex items-center gap-2">
      <h3 className="text-base font-medium">{section.title}</h3>
      {section.count !== undefined ? (
        <Badge variant={onBand ? "outline" : "secondary"}>
          {section.count}
        </Badge>
      ) : null}
    </div>
  );
}

function TitleRowTake() {
  const { on, set } = useToggles();
  return (
    <div className="flex flex-col gap-4">
      {SECTIONS.map((section) => (
        <Card key={section.id}>
          <CardContent className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <div className="flex h-8 items-center justify-between gap-4">
                <Title section={section} />
                <Control
                  on={on[section.id]}
                  onToggle={(value) => set(section.id, value)}
                  section={section}
                />
              </div>
              <p className="max-w-2xl text-sm text-muted-foreground">
                {section.description}
              </p>
            </div>
            {on[section.id] ? <Body id={section.id} /> : null}
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

function BandTake() {
  const { on, set } = useToggles();
  return (
    <div className="flex flex-col gap-4">
      {SECTIONS.map((section) => (
        <Card key={section.id}>
          <div className="-mt-(--card-spacing) flex h-12 items-center justify-between gap-4 border-b bg-muted/60 px-4">
            <Title onBand section={section} />
            <Control
              on={on[section.id]}
