      {TAKES.map(({ id, View }) => (
        <TabsContent key={id} value={id}>
          <div className="flex flex-col gap-6">
            <PageHeader title="Payment reminder" />
            <View />
          </div>
        </TabsContent>
      ))}
    </SecondaryTabs>
  );
}

